// facts-lib.mjs — shared helpers for the temporal facts layer.
//
// Sprint 46.6.1 — Agent OS Memory v2: Temporal Facts Layer.
// JSONL is the source of truth (committed, append-only). This module provides
// the read/write/query primitives. The deferred sqlite cache from the spec is
// not generated by default — at 60 facts the JSONL scan is sub-millisecond and
// a native sqlite dep adds install friction without a perf benefit. The format
// is forward-compatible: a future sprint can derive a sqlite cache from the
// same JSONL without changing any caller.

import { readFileSync, appendFileSync, existsSync, writeFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { join } from 'node:path';

export const REPO_ROOT = process.cwd();
export const JSONL_PATH = join(REPO_ROOT, 'agent-os/facts.jsonl');

// ── ID derivation: deterministic so duplicate appends become a no-op ────
export function factId(subject, predicate, object, valid_from) {
  const key = `${subject}|${predicate}|${object}|${valid_from || ''}`;
  return 'f_' + createHash('sha256').update(key).digest('hex').slice(0, 16);
}

// ── Read all facts (returns array, parses every line) ────────────────────
export function readAllFacts() {
  if (!existsSync(JSONL_PATH)) return [];
  const text = readFileSync(JSONL_PATH, 'utf8');
  const out = [];
  let lineNo = 0;
  for (const line of text.split(/\r?\n/)) {
    lineNo++;
    if (!line.trim()) continue;
    try {
      out.push(JSON.parse(line));
    } catch (e) {
      throw new Error(`facts.jsonl line ${lineNo} failed JSON.parse: ${e.message}`);
    }
  }
  return out;
}

// ── Append (idempotent on identical content) ─────────────────────────────
//
// Dedup key is (subject|predicate|object|valid_from|valid_to) — the fact's
// observable shape. The deterministic `id` only includes (s,p,o,valid_from)
// so legitimate invalidations (same fact, new valid_to) intentionally share
// an id with the original line. Two lines with the same id is the encoding
// of "this fact's status changed" — readers fold by latest `extracted_at`.
export function appendFact(fact) {
  const existing = readAllFacts();
  const sameShape = (a, b) =>
    a.subject === b.subject &&
    a.predicate === b.predicate &&
    a.object === b.object &&
    (a.valid_from || null) === (b.valid_from || null) &&
    (a.valid_to || null) === (b.valid_to || null);
  if (existing.some(f => sameShape(f, fact))) return { written: false, reason: 'duplicate' };
  const line = JSON.stringify(fact) + '\n';
  appendFileSync(JSONL_PATH, line, 'utf8');
  return { written: true };
}

// ── Validate inputs for `facts-append.sh` ────────────────────────────────
export function validateInput({ subject, predicate, object, valid_from, valid_to }) {
  const errors = [];
  if (!subject || !subject.trim()) errors.push('subject is empty');
  if (!predicate || !predicate.trim()) errors.push('predicate is empty');
  if (!object || !object.trim()) errors.push('object is empty');
  const dateRe = /^\d{4}-\d{2}-\d{2}$/;
  if (valid_from && !dateRe.test(valid_from)) errors.push(`valid_from "${valid_from}" is not ISO-8601 (YYYY-MM-DD)`);
  if (valid_to && !dateRe.test(valid_to)) errors.push(`valid_to "${valid_to}" is not ISO-8601 (YYYY-MM-DD)`);
  return errors;
}

// ── Query: fold history, then apply the temporal filter ──────────────────
//
// Two facts share an id ⇒ they describe the same (subject, predicate, object,
// valid_from) tuple at different points in its life (the invalidation pattern).
// The reader collapses the history by keeping the most recent `extracted_at`
// per id — that line is the *current truth* about the fact.
//
// Then the temporal filter applies:
//   asOf is null → match any
//   asOf is set  → valid_from <= asOf AND (valid_to IS NULL OR valid_to >= asOf)
function foldHistory(facts) {
  // The JSONL is read in file order, which equals append order — append-only
  // semantics mean "later in file = later mutation". Prefer the row with a
  // later `extracted_at`, breaking ties on file position so a same-second
  // invalidation (the AC-5 case) still picks up the close.
  const latest = new Map();
  facts.forEach((f, idx) => {
    const key = f.id || `${f.subject}|${f.predicate}|${f.object}|${f.valid_from || ''}`;
    const prev = latest.get(key);
    if (
      !prev ||
      ((f.extracted_at || '') > (prev._fact.extracted_at || '')) ||
      ((f.extracted_at || '') === (prev._fact.extracted_at || '') && idx > prev._idx)
    ) {
      latest.set(key, { _fact: f, _idx: idx });
    }
  });
  return Array.from(latest.values()).map(w => w._fact);
}

export function queryFacts({ subject, predicate, object, asOf } = {}) {
  const folded = foldHistory(readAllFacts());
  return folded.filter(f => {
    if (subject && f.subject !== subject) return false;
    if (predicate && f.predicate !== predicate) return false;
    if (object && f.object !== object) return false;
    if (asOf) {
      if (f.valid_from && f.valid_from > asOf) return false;
      if (f.valid_to && f.valid_to < asOf) return false;
    }
    return true;
  });
}

// ── Pretty-print one fact for CLI output ─────────────────────────────────
export function formatFactLine(f) {
  const valid = f.valid_to ? `${f.valid_from}..${f.valid_to}` : `${f.valid_from || '-'}..`;
  return `${f.id}  ${f.subject}  ${f.predicate}  ${f.object}  [${valid}]  src=${f.source_file || '-'}  sprint=${f.sprint || '-'}`;
}

export function nowIsoSeconds() {
  return new Date().toISOString().replace(/\.\d{3}Z$/, 'Z');
}
